-- A portrait per composer (Wikimedia Commons via Wikidata; for composers of
-- this age the paintings and photographs are out of copyright). Shown beside
-- each piece in sign-up step 4 and in Admin → Composers & pieces.
-- Packed as base64 JSON so the SQL editor has nothing to misread. Safe to re-run.
alter table public.composers add column if not exists photo_url text;

update public.composers c set photo_url = v.u
from json_to_recordset(convert_from(decode('', 'base64'), 'UTF8')::json) as v(n text, u text)
where c.name = v.n;
